import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
g=G['Test input']
from collections import Counter
H=len(g); W=len(g[0])
bg=Counter(x for r in g for x in r).most_common(1)[0][0]
seen=[[False]*W for _ in range(H)]
def comp(i,j):
    st=[(i,j)]; cells=[]
    while st:
        a,b=st.pop()
        if a<0 or b<0 or a>=H or b>=W or seen[a][b] or g[a][b]!=g[i][j]: continue
        seen[a][b]=True; cells.append((a,b))
        for da in(-1,0,1):
            for db in(-1,0,1): st.append((a+da,b+db))
    return cells
out=[r[:] for r in g]
for i in range(H):
    for j in range(W):
        if g[i][j]!=bg and not seen[i][j]:
            cs=comp(i,j); v=g[i][j]
            # bounding box of component
            rs=[c[0] for c in cs]; cl=[c[1] for c in cs]
            r0,r1,c0,c1=min(rs),max(rs),min(cl),max(cl)
            if len(set(cs))==len(cs):  # rectangle, full fill
                for a in range(r0,r1+1):
                    for b in range(c0,c1+1):
                        out[a][b]=v if a in(r0,r1) or b in(c0,c1) else 8
print(json.dumps(out))
